CREATE OR REPLACE FUNCTION public.is_admin_or_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT private.is_admin() OR public.is_staff(); $$;
CREATE OR REPLACE FUNCTION public.admin_set_staff_capability(p_user_id uuid,p_capability text,p_enabled boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT private.is_admin() THEN RAISE EXCEPTION 'Yetkisiz'; END IF; IF NOT EXISTS (SELECT 1 FROM public.permission_catalog WHERE key=p_capability AND active=true) THEN RAISE EXCEPTION 'Geçersiz yetki'; END IF; INSERT INTO public.staff_permissions(user_id,permission_key,enabled,updated_at) VALUES(p_user_id,p_capability,p_enabled,now()) ON CONFLICT(user_id,permission_key) DO UPDATE SET enabled=excluded.enabled,updated_at=now(); UPDATE public.staff_profiles SET permissions=coalesce(permissions,'{}'::jsonb)||jsonb_build_object(p_capability,p_enabled),updated_at=now() WHERE user_id=p_user_id; RETURN jsonb_build_object('ok',true,'user_id',p_user_id,'permission',p_capability,'enabled',p_enabled); END; $$;
CREATE OR REPLACE FUNCTION public.admin_set_staff_capabilities(p_user_id uuid,p_permissions jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE k text; v boolean; BEGIN IF NOT private.is_admin() THEN RAISE EXCEPTION 'Yönetici yetkisi gerekli'; END IF; IF NOT EXISTS (SELECT 1 FROM public.staff_profiles WHERE user_id=p_user_id AND role<>'admin') THEN RAISE EXCEPTION 'Personel hesabı bulunamadı'; END IF; IF jsonb_typeof(coalesce(p_permissions,'{}'::jsonb))<>'object' THEN RAISE EXCEPTION 'Geçersiz yetki verisi'; END IF; DELETE FROM public.staff_permissions WHERE user_id=p_user_id; FOR k,v IN SELECT key,value::boolean FROM jsonb_each(coalesce(p_permissions,'{}'::jsonb)) LOOP IF EXISTS (SELECT 1 FROM public.permission_catalog WHERE key=k AND active=true) THEN INSERT INTO public.staff_permissions(user_id,permission_key,enabled,updated_at) VALUES(p_user_id,k,coalesce(v,false),now()); END IF; END LOOP; RETURN jsonb_build_object('ok',true,'user_id',p_user_id); END; $$;
CREATE OR REPLACE FUNCTION public.admin_update_business_settings(p_values jsonb) RETURNS public.business_settings LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.business_settings; BEGIN IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin yetkisi gerekli'; END IF; UPDATE public.business_settings SET business_name=coalesce(p_values->>'business_name',business_name),phone=coalesce(p_values->>'phone',phone),whatsapp=coalesce(p_values->>'whatsapp',whatsapp),email=coalesce(p_values->>'email',email),instagram=coalesce(p_values->>'instagram',instagram),quote_valid_days=coalesce((p_values->>'quote_valid_days')::int,quote_valid_days),min_quote=coalesce((p_values->>'min_quote')::numeric,min_quote),default_margin=coalesce((p_values->>'default_margin')::numeric,default_margin),currency=coalesce(p_values->>'currency',currency),tax_rate=coalesce((p_values->>'tax_rate')::numeric,tax_rate),quote_number_prefix=coalesce(p_values->>'quote_number_prefix',quote_number_prefix),default_quote_valid_days=coalesce((p_values->>'default_quote_valid_days')::int,default_quote_valid_days),default_event_duration_hours=coalesce((p_values->>'default_event_duration_hours')::numeric,default_event_duration_hours),notify_new_offer=coalesce((p_values->>'notify_new_offer')::boolean,notify_new_offer),notify_offer_evaluation=coalesce((p_values->>'notify_offer_evaluation')::boolean,notify_offer_evaluation),notify_event_change=coalesce((p_values->>'notify_event_change')::boolean,notify_event_change),updated_at=now() WHERE id=true RETURNING * INTO r; INSERT INTO public.activity_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(),'business_settings_updated','business_settings',null,p_values-jsonb_build_object('secrets','redacted')); RETURN r; END; $$;
CREATE OR REPLACE FUNCTION public.current_admin_profile() RETURNS TABLE(username text,display_name text,active boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p.username,p.display_name,p.active FROM public.admin_profiles p WHERE p.user_id=auth.uid() AND p.active=true LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.panel_access(p_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT CASE p_kind WHEN 'admin' THEN private.is_admin() WHEN 'staff' THEN public.is_staff() ELSE false END; $$;
